"""Regression for CR and CRLF generated by the model inside carrier texts."""
from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

import pytest

from vkr_benchmark.errors import ConfigurationError
from vkr_benchmark.steganalysis.textio import read_carrier_text, write_carrier_text

ROOT = Path(__file__).resolve().parents[2]


def _sha(value: str) -> str:
    return hashlib.sha256(value.encode('utf-8')).hexdigest()


def test_lossless_carrier_text_io_handles_cr_crlf_and_unicode(tmp_path: Path):
    value = 'First\rsecond\r\nThird\nUnicode: é 中 📚'
    path = tmp_path / 'stegotext.txt'
    write_carrier_text(path, value)
    assert path.read_bytes() == value.encode('utf-8')
    assert read_carrier_text(path) == value
    assert _sha(read_carrier_text(path)) == hashlib.sha256(path.read_bytes()).hexdigest()
    assert path.read_text(encoding='utf-8') != value  # universal-newline bug


def test_resume_skips_unchanged_carrier_with_cr_and_detects_true_tampering(tmp_path: Path):
    sys.path.insert(0, str(ROOT / 'scripts'))
    try:
        from generate_stage7_stegos import _verify_existing
    finally:
        sys.path.pop(0)
    run = tmp_path / 'run'
    run.mkdir()
    text = 'Text with CR\rpart two\r\npart three'
    write_carrier_text(run / 'stegotext.txt', text)
    (run / 'token_ids.json').write_text(json.dumps({'sender_token_ids': [4]*256}), encoding='utf-8')
    row = {'stego_run_id': 'run', 'sample_id': 'sample', 'method_id': 'bins',
           'canonical_run_config': {'method': 'test'}}
    result = {'run_id': 'run', 'sample_id': 'sample', 'carrier_tokens': 256,
              'text_sha256': _sha(text), 'canonical_run_config': row['canonical_run_config']}
    (run / 'stego_result.json').write_text(json.dumps(result), encoding='utf-8')
    assert _verify_existing(run, row) is True
    # No changing metadata or automatically trusting a normalized version.
    assert read_carrier_text(run / 'stegotext.txt') == text
    (run / 'stegotext.txt').write_bytes(text.replace('\r', '\n').encode('utf-8'))
    with pytest.raises(ConfigurationError, match='text hash mismatch'):
        _verify_existing(run, row)


def test_invalid_utf8_carrier_fails_closed(tmp_path: Path):
    path = tmp_path / 'broken.txt'
    path.write_bytes(b'\xff\xfe')
    with pytest.raises(ConfigurationError, match='exact UTF-8 carrier'):
        read_carrier_text(path)
